# region: digest
def digest(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: gather
def gather(xs):
    return [v * v for v in xs]

# region: render
def render(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: fold
def fold(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: shape
def shape(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return shape(fold(render(gather(digest(raw)))))

